import React from 'react';
import Chatbot from './components/Chatbot';

function App() {
  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #f0f4f8, #d9e2ec)',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <div style={{ maxWidth: '700px', margin: '0 auto' }}>
        <h1 style={{ textAlign: 'center', color: '#2c3e50' }}>
          Mental Health Companion
        </h1>
        <p style={{ 
          textAlign: 'center', 
          color: '#555', 
          marginBottom: '24px' 
        }}>
          I'm here to listen and support you — but I'm not a replacement for professional help.<br />
          If you're in crisis, please call a helpline right away (e.g., 1Life: 78930-78930).
        </p>

        <div style={{
          background: 'white',
          borderRadius: '16px',
          boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
          overflow: 'hidden'
        }}>
          <Chatbot />
        </div>
      </div>
    </div>
  );
}

export default App;
